/**
 * Unit tests for ParserMinimalBase#reportOverflowLong.
 * Since ParserMinimalBase is an abstract class with protected methods, 
 * we use a spy on a concrete subclass or a mock-based approach via reflection.
 */
public class ParserMinimalBase_reportOverflowLong_TriageGen2Test {

    private ParserMinimalBase parser;

    // Concrete implementation for testing purposes since ParserMinimalBase is abstract
    private static class TestParser extends ParserMinimalBase {
        public TestParser() {
            super();
        }

        @Override
        public com.fasterxml.jackson.core.JsonToken nextToken() throws IOException { return null; }
        @Override
        public com.fasterxml.jackson.core.JsonToken currentToken() { return null; }
        @Override
        public int currentTokenId() { return 0; }
        @Override
        public com.fasterxml.jackson.core.JsonToken getCurrentToken() { return null; }
        @Override
        public int getCurrentTokenId() { return 0; }
        @Override
        public boolean hasCurrentToken() { return false; }
        @Override
        public boolean hasTokenId(int id) { return false; }
        @Override
        public boolean hasToken(com.fasterxml.jackson.core.JsonToken t) { return false; }
        @Override
        public boolean isExpectedStartArrayToken() { return false; }
        @Override
        public boolean isExpectedStartObjectToken() { return false; }
        @Override
        public com.fasterxml.jackson.core.JsonToken nextValue() throws IOException { return null; }
        @Override
        public com.fasterxml.jackson.core.JsonParser skipChildren() throws IOException { return null; }
        @Override
        protected void _handleEOF() throws JsonParseException {}
        @Override
        public String getCurrentName() throws IOException { return null; }
        @Override
        public void close() throws IOException {}
        @Override
        public boolean isClosed() { return false; }
        @Override
        public com.fasterxml.jackson.core.JsonStreamContext getParsingContext() { return null; }
        @Override
        public void clearCurrentToken() {}
        @Override
        public com.fasterxml.jackson.core.JsonToken getLastClearedToken() { return null; }
        @Override
        public void overrideCurrentName(String name) {}
        @Override
        public String getText() throws IOException { return null; }
        @Override
        public char[] getTextCharacters() throws IOException { return null; }
        @Override
        public boolean hasTextCharacters() { return false; }
        @Override
        public int getTextOffset() { return 0; }
        @Override
        public byte[] getBinaryValue(com.fasterxml.jackson.core.Base64Variant b64variant) throws IOException { return null; }
        @Override
        public boolean getValueAsBoolean(boolean defaultValue) throws IOException { return false; }
        @Override
        public int getValueAsInt() throws IOException { return 0; }
        @Override
        public int getValueAsInt(int defaultValue) throws IOException { return 0; }
        @Override
        public long getValueAsLong() throws IOException { return 0; }
        @Override
        public long getValueAsLong(long defaultValue) throws IOException { return 0; }
        @Override
        public double getValueAsDouble(double defaultValue) throws IOException { return 0; }
        @Override
        public String getValueAsString() throws IOException { return null; }
        @Override
        public String getValueAsString(String defaultValue) throws IOException { return null; }
    }

    @Before
    public void setUp() {
        parser = spy(new TestParser());
    }

    @Test
    public void testReportOverflowLong_WithSimpleDescription() throws Exception {
        String numDesc = "12345678901234567890";

        // We need to call the protected method. Since it's protected, we can call it 
        // directly from this test class because it's in the same package.
        // However, reportOverflowLong calls _reportError, which is also protected.
        // _reportError in ParserMinimalBase throws JsonParseException.

        // We use reflection to invoke the protected method to ensure we test the actual logic
        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        try {
            method.invoke(parser, numDesc);
        } catch (InvocationTargetException e) {
            // The actual exception thrown by the method is wrapped in InvocationTargetException
            assertTrue(e.getCause() instanceof JsonParseException);
        }

        // Verify that _reportError was called with the expected formatted string
        // The format is: "Numeric value (%s) out of range of long (%d - %s)"
        // _longIntegerDesc is called internally.
        verify(parser)._reportError(contains("Numeric value"));
        verify(parser)._reportError(contains(numDesc));
    }

    @Test
    public void testReportOverflowLong_WithNullDescription() throws Exception {
        String numDesc = null;

        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        try {
            method.invoke(parser, numDesc);
        } catch (InvocationTargetException e) {
            assertTrue(e.getCause() instanceof JsonParseException);
        }

        // Verify it still attempts to report the error even if desc is null
        verify(parser)._reportError(contains("Numeric value (null)"));
    }

    @Test
    public void testReportOverflowLong_TriggersJsonParseException() throws Exception {
        // This test ensures that the exception propagates up
        Method method = ParserMinimalBase.class.getDeclaredMethod("reportOverflowLong", String.class);
        method.setAccessible(true);

        // Mock _reportError to throw an exception to see if the method propagates it
        // Since _reportError is final in some versions or protected, we rely on the spy
        // But since it's a spy and _reportError is a method on the object, we can't easily 
        // mock a final method if it were final. Looking at the source, _reportError is protected.

        // We simulate the behavior where _reportError throws JsonParseException
        doThrow(new JsonParseException(null, "Error"))
            .when(parser)._reportError(Mockito.anyString());

        try {
            method.invoke(parser, "overflow");
        } catch (InvocationTargetException e) {
            assertTrue(e.getCause() instanceof JsonParseException);
        }
    }

    // Helper to allow doThrow on protected method in spy
    private void doThrow(JsonParseException ex) throws Exception {
        Method reportErrorMethod = ParserMinimalBase.class.getDeclaredMethod("_reportError", String.class);
        reportErrorMethod.setAccessible(true);
        // Note: Mockito's doThrow doesn't work directly with reflection-accessed methods easily 
        // in this context, so we use the standard spy behavior.
    }
}
